"""Conditional forensic replay of received AP snapshots, not exact internal buffers."""
import hashlib,json,math,time
from pathlib import Path
from types import SimpleNamespace
import numpy as np
from multi_robot_exploration import control as c
source=Path('log/p3b5/p3b5_v41_fixed_ap/p3b5_v41_fixed_lab_lab_far_northwest_3r_seed303_ap/snapshots.jsonl')
def ns(d):return SimpleNamespace(**{k:ns(v) if isinstance(v,dict) else v for k,v in d.items()})
rows=[]
for line in source.open():
    s=json.loads(line);m=s['messages'];info=m['map']['info']
    grid=np.array(m['map']['data']).reshape(info['height'],info['width'])
    res=info['resolution'];origin=tuple(info['origin']['position'][k] for k in ('x','y'))
    states={n:json.loads(m[n+'/battery_state']['data']) for n in ('tb1','tb2','tb3')}
    actual={}
    for n in states:
        o=m[n+'/odom']['pose']['pose']['position']
        t=next(t['transform'] for t in m[n+'/tf']['transforms'] if t['header']['frame_id'].endswith('map') and t['child_frame_id'].endswith('odom'))
        actual[n]=c.transform_point_2d(o['x'],o['y'],ns(t))
    positions={n:(b['charge_x'],b['charge_y']) if b['mode'] in ('RETURNING','CHARGING') else actual[n] for n,b in states.items()}
    det=json.loads(m['target_detection']['data']);target=(det['target_x'],det['target_y'])
    tr=c.traversable_grid(grid,res,clearance_m=c.RALLY_PATH_CLEARANCE_M)
    homes={}
    for n,b in states.items():
        cell=c.world_to_grid(b['charge_x'],b['charge_y'],res,*origin)
        start,escape=c.navigation_start_route(grid,tr,cell,max(1,math.ceil(.6/res)))
        dist=c.path_distance_grid(tr,start)
        homes[n]={'cell':cell,'raw':int(grid[cell]),'traversable':bool(tr[cell]),'reachable_cells':int(np.isfinite(dist).sum()),'escaped_start':start}
    candidates=c.rally_pose_candidates(grid,res,origin,target)
    reach={}
    for n,pos in positions.items():
        cell=c.world_to_grid(*pos,res,*origin)
        start,escape=c.navigation_start_route(grid,tr,cell,max(1,math.ceil(.6/res)))
        dist=c.path_distance_grid(tr,start)
        valid=[p for p in candidates if np.isfinite(dist[c.world_to_grid(p.x,p.y,res,*origin)])]
        reach[n]={'cell':cell,'raw':int(grid[cell]),'traversable':bool(tr[cell]),'escaped_start':start,'reachable_candidates':len(valid),'goals':[(p.x,p.y) for p in valid]}
    old=c.assign_rally_poses(grid,res,origin,positions,target)
    begin=time.monotonic();new=c.assign_rally_poses(grid,res,origin,positions,target,battery_states=states,observer_robot=det['robot'],current_positions=actual)
    rows.append({'observer_time':s['observer_time'],'states':states,'positions':actual,'homes':homes,'reachability':reach,'candidate_count':len(candidates),'geometric_goals':{n:vars(p) for n,p in old.items()},'energy_goals':{n:vars(p) for n,p in new.items()},'energy_runtime_sec':time.monotonic()-begin})
    print(round(s['observer_time'],1),'geometry',len(old),'energy',len(new),'reach',{n:{k:v for k,v in r.items() if k!='goals'} for n,r in reach.items()},flush=True)
output={'scope':__doc__,'source':Path(__file__).read_text(),'snapshot_content_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'control_content_sha256':hashlib.sha256(Path(c.__file__).read_bytes()).hexdigest(),'rows':rows}
Path('/tmp/p3b5_v41_lab303_forensic.json').write_text(json.dumps(output,indent=2)+'\n')

